code.text:
processors:
  tail_sampling:
    decision_wait: 15s
    num_traces: 200000
    policies:
      - { name: errors, type: status_code, status_code: { status_codes: [ERROR] } }
      - { name: slow,   type: latency, latency: { threshold_ms: 1000 } }
      - { name: vip,    type: string_attribute, string_attribute: { key: tenant.tier, values: [enterprise] } }
      - { name: rest,   type: probabilistic, probabilistic: { sampling_percentage: 2 } }

exporters:
  loadbalancing:
    routing_key: traceID
    protocol: { otlp: { tls: { insecure: true } } }
    resolver:
      k8s: { service: otel-sampler.observability, ports: [4317] }
service:
  pipelines:
    traces: { receivers: [otlp], exporters: [loadbalancing] }
